(1923815, 263996, 6519, '<td valign="top">You did well to pick very clean and unscratched utensils. Together with the neat lineup in a pleasing diagonal, this simple composition works well. The "elixir" came almost as a surprise with its little splash of understated color. The only distracting part are all those reflections in the spoon. 7</td>', 'You did well to pick very clean and unscratched utensils. Together with the neat lineup in a pleasing diagonal, this simple composition works well. The "elixir" came almost as a surprise with its little splash of understated color. The only distracting part are all those reflections in the spoon. 7', '2005-12-05 12:32:08.000000', NULL, 1),
(1923816, 265454, 34013, '<td valign="top">awesome shot. nice selective color!</td>', 'awesome shot. nice selective color!', '2005-12-05 12:32:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1923819, 265407, 34013, '<td valign="top">reminds me of dying easter eggs! :)</td>', 'reminds me of dying easter eggs! :)', '2005-12-05 12:32:45.000000', NULL, 1),
(1923824, 264290, 6519, '<td valign="top">I love the composition, the angles and the colors. Only thing I''d do differently is to have the focus in a different spot, or a slightly bigger DOF. 7</td>', 'I love the composition, the angles and the colors. Only thing I''d do differently is to have the focus in a different spot, or a slightly bigger DOF. 7', '2005-12-05 12:33:40.000000', NULL, 1),
(1923830, 264857, 1041, '<td valign="top">Nice white background, although, looking at the shadows, you seem to have achieved a good part of it in post-processing.  It''s hard though with reflective items.  Nice arrangement and (even though I don''t understand the latin phrase), easy to guess what the meaning is.    Some overblown highlights in the forks and I wish it was a tad sharper.</td>', 'Nice white background, although, looking at the shadows, you seem to have achieved a good part of it in post-processing.  It''s hard though with reflective items.  Nice arrangement and (even though I don''t understand the latin phrase), easy to guess what the meaning is.    Some overblown highlights in the forks and I wish it was a tad sharper.', '2005-12-05 12:34:41.000000', NULL, 1),
(1923831, 263855, 318, '<td valign="top">Good idea, good composition, not so good post-processing. Too much burnout for my taste.</td>', 'Good idea, good composition, not so good post-processing. Too much burnout for my taste.', '2005-12-05 12:34:55.000000', NULL, 1),
(1923832, 265248, 6519, '<td valign="top">The color of the sky is a bit much, but I love the point of view / angle you chose for this.  7</td>', 'The color of the sky is a bit much, but I love the point of view / angle you chose for this.  7', '2005-12-05 12:34:58.000000', NULL, 1),
(1923838, 265413, 19672, '<td valign="top">a touch grainy but otherwise a cute concept</td>', 'a touch grainy but otherwise a cute concept', '2005-12-05 12:37:43.000000', NULL, 1),
(1923841, 265466, 6519, '<td valign="top">Cute idea with room for improvement (straight floor, crisper focus and improved lighting). Perhaps your model could grip the fork a bit tighter and push down on it to help the illusion look a little more realistic. 5</td>', 'Cute idea with room for improvement (straight floor, crisper focus and improved lighting). Perhaps your model could grip the fork a bit tighter and push down on it to help the illusion look a little more realistic. 5', '2005-12-05 12:38:18.000000', NULL, 1),
(1923849, 265394, 40679, '<td valign="top">I really love the reds &amp; purples and the idea, but I guess it''s a little out of focus, or maybe you used a large aperture??</td>', 'I really love the reds & purples and the idea, but I guess it''s a little out of focus, or maybe you used a large aperture??', '2005-12-05 12:40:01.000000', NULL, 1),
