(1925154, 264396, 22734, '<td valign="top">Returning for comments:<br/>A classical composition with that center bullseye resting place. I am a little confused with the light shadow play beneath the meeting of the fork blades. However, excepting this very minor distraction the eye is able to examine the lovely tonal texture of each fork and the pleasant fading into medium darkness of the background.</td>', 'Returning for comments:A classical composition with that center bullseye resting place. I am a little confused with the light shadow play beneath the meeting of the fork blades. However, excepting this very minor distraction the eye is able to examine the lovely tonal texture of each fork and the pleasant fading into medium darkness of the background.', '2005-12-05 20:39:36.000000', NULL, 1),
(1925158, 262979, 22734, '<td valign="top">Returning for comments:<br/>A very nice color study with a dandy title. The reflections are dazzling.</td>', 'Returning for comments:A very nice color study with a dandy title. The reflections are dazzling.', '2005-12-05 20:40:24.000000', NULL, 1),
