(1928600, 265445, 22734, '<td valign="top">A very neat presentation. Love the blue at the base of handle.</td>', 'A very neat presentation. Love the blue at the base of handle.', '2005-12-06 19:23:51.000000', NULL, 1),
(1928610, 265297, 22734, '<td valign="top">Very nice idea. It works as is but I would have explored different focusing points and various dof. Yet, as is, the eye can not fail to zero into the lead. The tablerop or background shade is cool. Bumping up.</td>', 'Very nice idea. It works as is but I would have explored different focusing points and various dof. Yet, as is, the eye can not fail to zero into the lead. The tablerop or background shade is cool. Bumping up.', '2005-12-06 19:27:35.000000', NULL, 1),
(1928773, 265380, 14211, '<td valign="top">this HAS to be number1......you are so creative...... of course the excellent taste in the jewels  selection helped a bit.,,,to be serious I love it love it love it .</td>', 'this HAS to be number1......you are so creative...... of course the excellent taste in the jewels  selection helped a bit.,,,to be serious I love it love it love it .', '2005-12-06 20:14:55.000000', NULL, 1),
(1928909, 265379, 27763, '<td valign="top">Great portrait.  Beautiful lighting, tones, and clarity.  Oh, and the forked tongue thing is a clever touch, too!</td>', 'Great portrait.  Beautiful lighting, tones, and clarity.  Oh, and the forked tongue thing is a clever touch, too!', '2005-12-06 20:59:24.000000', NULL, 1),
(1928914, 265397, 27763, '<td valign="top">Cute family portrait.  I like how the individual people don''t look too posed.</td>', 'Cute family portrait.  I like how the individual people don''t look too posed.', '2005-12-06 21:01:21.000000', NULL, 1),
