(1929362, 265469, 18780, '<td valign="top">fantastic perspective!</td>', 'fantastic perspective!', '2005-12-06 22:19:53.000000', NULL, 1),
(1929395, 264991, 46467, '<td valign="top">EEE-LECTRIC!!!  Very nice distribution of color throughout the forks!  Nice addition of background lightshow.  Shazam!</td>', 'EEE-LECTRIC!!!  Very nice distribution of color throughout the forks!  Nice addition of background lightshow.  Shazam!', '2005-12-06 22:32:33.000000', NULL, 1),
(1929398, 264727, 10263, '<td valign="top">This is beautiful. My only 10 in the challenge.</td>', 'This is beautiful. My only 10 in the challenge.', '2005-12-06 22:34:19.000000', NULL, 1),
(1929399, 265389, 46467, '<td valign="top">Nice!</td>', 'Nice!', '2005-12-06 22:34:30.000000', NULL, 1),
(1929401, 265389, 5112, '<td valign="top">Beautiful, vibrant and colourful.  Love the square crop.  Good use of the rule of thirds.  It looks a bit overprocessed, but I''m thinking that was your goal here.  The shallow DOF is an interesting problem here, it works for the fork tips, but it also gets part of the foreground (chair arm???) in focus, just a little strip of it, and I''m wondering if that''s good or not.</td>', 'Beautiful, vibrant and colourful.  Love the square crop.  Good use of the rule of thirds.  It looks a bit overprocessed, but I''m thinking that was your goal here.  The shallow DOF is an interesting problem here, it works for the fork tips, but it also gets part of the foreground (chair arm???) in focus, just a little strip of it, and I''m wondering if that''s good or not.', '2005-12-06 22:34:53.000000', NULL, 1),
(1929403, 265210, 46467, '<td valign="top">NIce depth and shadowing.</td>', 'NIce depth and shadowing.', '2005-12-06 22:35:06.000000', NULL, 1),
(1929404, 265068, 46467, '<td valign="top">Clever!</td>', 'Clever!', '2005-12-06 22:35:19.000000', NULL, 1),
(1929409, 265379, 7485, '<td valign="top">Ingenious! Very well executed too</td>', 'Ingenious! Very well executed too', '2005-12-06 22:35:43.000000', NULL, 1),
(1929410, 265288, 46467, '<td valign="top">Far out!!</td>', 'Far out!!', '2005-12-06 22:35:43.000000', NULL, 1),
(1929411, 265413, 10263, '<td valign="top">This is wonderful. So funny and creative. Amazing what you can do with a woody :)</td>', 'This is wonderful. So funny and creative. Amazing what you can do with a woody :)', '2005-12-06 22:35:55.000000', NULL, 1),
(1929413, 263996, 46467, '<td valign="top">Simple, nice and with my favorite colour!</td>', 'Simple, nice and with my favorite colour!', '2005-12-06 22:37:46.000000', NULL, 1),
(1929424, 265399, 7485, '<td valign="top">Very interesting concept! But the orange cast is a problem, makes her skin color very unnattural. Also, it would have been neat if you could have had the blade reflect a light source, to draw the eye to the blade.</td>', 'Very interesting concept! But the orange cast is a problem, makes her skin color very unnattural. Also, it would have been neat if you could have had the blade reflect a light source, to draw the eye to the blade.', '2005-12-06 22:40:45.000000', NULL, 1),
(1929446, 265065, 7485, '<td valign="top">Brilliant idea! Did you make it?</td>', 'Brilliant idea! Did you make it?', '2005-12-06 22:47:21.000000', NULL, 1),
(1929448, 265251, 46467, '<td valign="top">Superb!</td>', 'Superb!', '2005-12-06 22:47:56.000000', NULL, 1),
(1929454, 265436, 44992, '<td valign="top">I thought this was quite funny... kind of insulting.  But I get the humor.<br/> <br/>Cute picture.</td>', 'I thought this was quite funny... kind of insulting.  But I get the humor. Cute picture.', '2005-12-06 22:49:59.000000', NULL, 1),
(1929460, 265407, 44992, '<td valign="top">This is beautiful and the kind of pictures I wish I could take.</td>', 'This is beautiful and the kind of pictures I wish I could take.', '2005-12-06 22:51:30.000000', NULL, 1),
(1929466, 265065, 46467, '<td valign="top">LOL!!!</td>', 'LOL!!!', '2005-12-06 22:52:07.000000', NULL, 1),
(1929469, 264290, 42714, '<td valign="top">Unfortunately, I think this suffers from lack of focus.  The part of the photo that is sharp and in focus is centered in the stem of these spoons, and I think it throws off the entire composition.</td>', 'Unfortunately, I think this suffers from lack of focus.  The part of the photo that is sharp and in focus is centered in the stem of these spoons, and I think it throws off the entire composition.', '2005-12-06 22:52:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1929480, 265458, 7485, '<td valign="top">Great concept! I particularly like how the four forks together look like one fork lying face down. But why such a small image? And worse yet, why so over-compressed? You realize the file is only 5.8KB?!? I hope you still have the original and upload a proper sized image without compression artifacts after the challenge, a photo this good deserves much better than this. 6 (would have been a 10)</td>', 'Great concept! I particularly like how the four forks together look like one fork lying face down. But why such a small image? And worse yet, why so over-compressed? You realize the file is only 5.8KB?!? I hope you still have the original and upload a proper sized image without compression artifacts after the challenge, a photo this good deserves much better than this. 6 (would have been a 10)', '2005-12-06 22:55:14.000000', NULL, 1),
(1929486, 264363, 42714, '<td valign="top">Great humanization of objects.  Simple and subtle.  My favorite entry in this particular theme.</td>', 'Great humanization of objects.  Simple and subtle.  My favorite entry in this particular theme.', '2005-12-06 22:57:11.000000', NULL, 1),
(1929489, 265248, 7485, '<td valign="top">Ah yes, good old Solfar. Good color contrast and composition.</td>', 'Ah yes, good old Solfar. Good color contrast and composition.', '2005-12-06 22:57:59.000000', NULL, 1),
(1929499, 265461, 7485, '<td valign="top">Very creative, and superb use of negative space. It''s amazing how that one tiny reflection in the eye just makes the whole image come together. 10</td>', 'Very creative, and superb use of negative space. It''s amazing how that one tiny reflection in the eye just makes the whole image come together. 10', '2005-12-06 23:01:28.000000', NULL, 1),
(1929506, 265098, 7485, '<td valign="top">Great expression!</td>', 'Great expression!', '2005-12-06 23:02:57.000000', NULL, 1),
(1929513, 264611, 7485, '<td valign="top">And another solfar photo! great background, just wish it didn''t extend out of the frame on the left and at top.</td>', 'And another solfar photo! great background, just wish it didn''t extend out of the frame on the left and at top.', '2005-12-06 23:05:21.000000', NULL, 1),
(1929520, 264363, 7485, '<td valign="top">Beautifully done. Love the subtle blue color and the simple shapes. 10</td>', 'Beautifully done. Love the subtle blue color and the simple shapes. 10', '2005-12-06 23:08:38.000000', NULL, 1),
(1929542, 265380, 7485, '<td valign="top">You won''t need to buy any crampons for the winter! Imaginative and very well executed.</td>', 'You won''t need to buy any crampons for the winter! Imaginative and very well executed.', '2005-12-06 23:14:25.000000', NULL, 1),
