(1929595, 264864, 41802, '<td valign="top">Very interesting perspective. The candlelight is defiantly the focus. Good job.</td>', 'Very interesting perspective. The candlelight is defiantly the focus. Good job.', '2005-12-06 23:29:27.000000', NULL, 1),
(1929598, 265398, 41802, '<td valign="top">Very different use of light and contrast the utensils.</td>', 'Very different use of light and contrast the utensils.', '2005-12-06 23:30:07.000000', NULL, 1),
