INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1935568, 265107, 75713, '<td valign="top">crisp/clean lines. nice</td>', 'crisp/clean lines. nice', '2005-12-08 14:17:53.000000', NULL, 1),
(1935576, 264402, 75713, '<td valign="top">really like the color.. the reflection on the fork catches the eye .. great photo</td>', 'really like the color.. the reflection on the fork catches the eye .. great photo', '2005-12-08 14:19:40.000000', NULL, 1),
(1935580, 265379, 75713, '<td valign="top">great photo - made me feel a bit like gagging though</td>', 'great photo - made me feel a bit like gagging though', '2005-12-08 14:20:38.000000', NULL, 1),
(1935581, 265208, 75713, '<td valign="top">like the colors</td>', 'like the colors', '2005-12-08 14:20:55.000000', NULL, 1),
(1935588, 265417, 75713, '<td valign="top">Another photo that is worthy on the wall of an upscale restaurant.</td>', 'Another photo that is worthy on the wall of an upscale restaurant.', '2005-12-08 14:23:22.000000', NULL, 1),
(1935852, 265257, 26679, '<td valign="top">the spoon and feather are beautiful, it is the background that is distracting for me. i would have preferd to see a simple plain colour used</td>', 'the spoon and feather are beautiful, it is the background that is distracting for me. i would have preferd to see a simple plain colour used', '2005-12-08 16:00:43.000000', NULL, 1),
(1935875, 263289, 35513, '<td valign="top">Quite a lot going on here!  I think that a bright colored background or surface for the flatware would help the individual pieces stand out a little more.</td>', 'Quite a lot going on here!  I think that a bright colored background or surface for the flatware would help the individual pieces stand out a little more.', '2005-12-08 16:10:41.000000', NULL, 1),
(1935881, 264290, 35513, '<td valign="top">Good composition and set up here.  I really like the angle and you''ve chosen good interesting spices to fill the spoons with.  I wish that the DOF was a little larger so that more of the spoons were in focus a little better.  Lighting looks good!</td>', 'Good composition and set up here.  I really like the angle and you''ve chosen good interesting spices to fill the spoons with.  I wish that the DOF was a little larger so that more of the spoons were in focus a little better.  Lighting looks good!', '2005-12-08 16:12:17.000000', NULL, 1),
(1935887, 265377, 35513, '<td valign="top">Very good clarity and lighting on this shot!  I think I would like to see a different color (other than white) for the wall behind the knife.  I think either a yellow or red would help bring out the print in the paper that''s so well reflected in the knife.</td>', 'Very good clarity and lighting on this shot!  I think I would like to see a different color (other than white) for the wall behind the knife.  I think either a yellow or red would help bring out the print in the paper that''s so well reflected in the knife.', '2005-12-08 16:13:46.000000', NULL, 1),
(1935893, 263067, 35513, '<td valign="top">Very nice set up and lovely colors on this shot!  I think perhaps that the shutter might have been open a little too long on this shot, as it looks like there''s some motion blur.  I really like the lighting and you chose a great color for the background.  Try shortening up the shutter time and/or using a tripod and I think it will come out crystal clear!</td>', 'Very nice set up and lovely colors on this shot!  I think perhaps that the shutter might have been open a little too long on this shot, as it looks like there''s some motion blur.  I really like the lighting and you chose a great color for the background.  Try shortening up the shutter time and/or using a tripod and I think it will come out crystal clear!', '2005-12-08 16:16:02.000000', NULL, 1),
(1935896, 265458, 35513, '<td valign="top">The lighting looks pretty good on this shot, but I wish I could see it at a larger size! :-)  Good composition on this shot...your eye gets drawn from the tines of the fork all the way down the handle.</td>', 'The lighting looks pretty good on this shot, but I wish I could see it at a larger size! :-)  Good composition on this shot...your eye gets drawn from the tines of the fork all the way down the handle.', '2005-12-08 16:17:08.000000', NULL, 1),
(1935904, 265480, 35513, '<td valign="top">Very interesting concept!  Great job on creativity for this shot.  The addition of some colored lights or perhaps some other ornaments might play off the silverware nicely.</td>', 'Very interesting concept!  Great job on creativity for this shot.  The addition of some colored lights or perhaps some other ornaments might play off the silverware nicely.', '2005-12-08 16:19:28.000000', NULL, 1),
(1935914, 265434, 35513, '<td valign="top">Good composition on this shot.  There are some distracting reflections in some of the flatware (bah!  silly ceilings!).  But everything is lined up well and I like the diagonal effect across the frame of the shot.  I might be interested to see this in color with some kind of "tuscan" colored surface beneath the silverware...mostly because of the really cool design on the bottom of the handles.</td>', 'Good composition on this shot.  There are some distracting reflections in some of the flatware (bah!  silly ceilings!).  But everything is lined up well and I like the diagonal effect across the frame of the shot.  I might be interested to see this in color with some kind of "tuscan" colored surface beneath the silverware...mostly because of the really cool design on the bottom of the handles.', '2005-12-08 16:22:33.000000', NULL, 1),
(1935920, 264139, 35513, '<td valign="top">Very creative shot!!!  Definitely one of a kind in this challenge :-)</td>', 'Very creative shot!!!  Definitely one of a kind in this challenge :-)', '2005-12-08 16:23:15.000000', NULL, 1),
(1935924, 265475, 35513, '<td valign="top">Lovelly colors in this shot, and I like how you utilized things around you to create a truly interesting background.  The lines of light in the bowl of the spoon are slightly distracting to me.  I love the green haze that surrounds the spoon!!  Can''t wait to find out how you did that!</td>', 'Lovelly colors in this shot, and I like how you utilized things around you to create a truly interesting background.  The lines of light in the bowl of the spoon are slightly distracting to me.  I love the green haze that surrounds the spoon!!  Can''t wait to find out how you did that!', '2005-12-08 16:24:49.000000', NULL, 1),
(1935929, 264598, 35513, '<td valign="top">Interesting composition.....while I find the stuff floating IN the bowl kinda yucky, I have to admit that there''s something about this photo that draws me in.  The lighting looks really neat!</td>', 'Interesting composition.....while I find the stuff floating IN the bowl kinda yucky, I have to admit that there''s something about this photo that draws me in.  The lighting looks really neat!', '2005-12-08 16:25:56.000000', NULL, 1),
