(1942107, 265065, 38234, '<td valign="top">LOL LOL LOL</td>', 'LOL LOL LOL', '2005-12-11 12:44:18.000000', NULL, 1),
(1942120, 264909, 22734, '<td valign="top">returning for comments.<br/>A lovely image and possibly the best capture in the talent. While the softbox light effect creates an ultra smooth transition of tones,  it does rob the silver of its bright highlights. However, the trade off is justified because it is replaced with great tonal beauty and gives the image a pleasant feel and one that invites the eyes back again.</td>', 'returning for comments.A lovely image and possibly the best capture in the talent. While the softbox light effect creates an ultra smooth transition of tones,  it does rob the silver of its bright highlights. However, the trade off is justified because it is replaced with great tonal beauty and gives the image a pleasant feel and one that invites the eyes back again.', '2005-12-11 12:56:22.000000', NULL, 1),
(1942199, 264536, 43565, '<td valign="top">I like the lighting.</td>', 'I like the lighting.', '2005-12-11 14:19:47.000000', NULL, 1),
