(1942312, 265379, 49337, '<td valign="top">boy if that ain''t the truth!</td>', 'boy if that ain''t the truth!', '2005-12-11 15:33:26.000000', NULL, 1),
(1942315, 263718, 8891, '<td valign="top">I think the technical photography in this quite fine. Not sure of the choice of costume, just looks odd.  There is a bit of reflection on the back of the spoon that I am straining to make out and I think it might have been done away with. Also the spoon might have been placed a bit lower and more right in this which might have avoided the reflection. I think your premise of it floating by the little magician would have been intact and maybe avoided the reflection. Very nice effort.</td>', 'I think the technical photography in this quite fine. Not sure of the choice of costume, just looks odd.  There is a bit of reflection on the back of the spoon that I am straining to make out and I think it might have been done away with. Also the spoon might have been placed a bit lower and more right in this which might have avoided the reflection. I think your premise of it floating by the little magician would have been intact and maybe avoided the reflection. Very nice effort.', '2005-12-11 15:34:17.000000', NULL, 1),
(1942318, 265431, 318, '<td valign="top">A bit chaotic. Although I''m not sure how you could have isolated the 3 forks better.</td>', 'A bit chaotic. Although I''m not sure how you could have isolated the 3 forks better.', '2005-12-11 15:36:32.000000', NULL, 1),
(1942319, 264915, 318, '<td valign="top">The whole spoon would have been better.</td>', 'The whole spoon would have been better.', '2005-12-11 15:37:04.000000', NULL, 1),
(1942320, 264727, 318, '<td valign="top">Good idea. Keep it simple.</td>', 'Good idea. Keep it simple.', '2005-12-11 15:37:24.000000', NULL, 1),
(1942321, 265251, 8891, '<td valign="top">A very inviting and well done set up, the lighting is fine and the detail good throughout. Looks like something you might see at a wedding.</td>', 'A very inviting and well done set up, the lighting is fine and the detail good throughout. Looks like something you might see at a wedding.', '2005-12-11 15:37:36.000000', NULL, 1),
