(1942332, 264878, 8891, '<td valign="top">Very nice set up, tones  and reflections. Great lighting.</td>', 'Very nice set up, tones  and reflections. Great lighting.', '2005-12-11 15:42:01.000000', NULL, 1),
(1942339, 265364, 8891, '<td valign="top">I think you needed to have a deeper DOF so the subjects were more in focus, or a shallow DOF with the flatware in focus and the lights not. The desat was a good idea and you thought your set up well.</td>', 'I think you needed to have a deeper DOF so the subjects were more in focus, or a shallow DOF with the flatware in focus and the lights not. The desat was a good idea and you thought your set up well.', '2005-12-11 15:47:24.000000', NULL, 1),
(1942349, 265041, 318, '<td valign="top">Very mysterious. Great idea and good execution.</td>', 'Very mysterious. Great idea and good execution.', '2005-12-11 15:54:00.000000', NULL, 1),
(1942356, 265478, 8891, '<td valign="top">I like the colors scheme in this. Not sure if the spoon reflection adds anything to it. There''s a bit of dust or a hot pixel or two that might have been deleted. I might not have gone so tight on this set up(oh...and I should be one to talk...I am a fill the frame addict...oy!) and maybe focused on the fork and not the spoon as the fork is sort of the title character and not the spoon. BTW like the title and choice of utensils.</td>', 'I like the colors scheme in this. Not sure if the spoon reflection adds anything to it. There''s a bit of dust or a hot pixel or two that might have been deleted. I might not have gone so tight on this set up(oh...and I should be one to talk...I am a fill the frame addict...oy!) and maybe focused on the fork and not the spoon as the fork is sort of the title character and not the spoon. BTW like the title and choice of utensils.', '2005-12-11 15:57:23.000000', NULL, 1),
(1942380, 265297, 39057, '<td valign="top">very good idea...could have been done a little better...but...take a look at my stuff...I shouldn''t talk!</td>', 'very good idea...could have been done a little better...but...take a look at my stuff...I shouldn''t talk!', '2005-12-11 16:14:53.000000', NULL, 1),
